export {
  RadioGroup,
  RadioGroupLegend,
  Radio,
  RadioIndicator,
} from "./radio-group";

import { tv, type VariantProps } from "tailwind-variants";

const radioGroup = tv({
  slots: {
    root: "group/radio-group flex flex-col items-start gap-1.5 text-foreground",
    legend: [
      "text-sm font-semibold text-foreground",
      "group-data-disabled/radio-group:opacity-50",
      "group-data-readonly/radio-group:opacity-60",
    ],
    radio: [
      "m-1 flex shrink-0 items-center justify-center rounded-full border border-input bg-background shadow-md transition-all duration-150 ease-default outline-none",
      "focus-visible:ring-2 focus-visible:ring-ring",
      "data-checked:bg-primary data-checked:text-primary-foreground",
      "data-disabled:pointer-events-none data-disabled:opacity-50",
      "data-invalid:border-destructive",
      "focus-visible:data-invalid:ring-destructive",
      "data-readonly:pointer-events-none data-readonly:opacity-60",
      "dark:bg-input/15",
      "dark:data-checked:bg-primary dark:data-checked:text-primary-foreground",
    ],
    radioIndicator: [
      "flex items-center justify-center transition-[scale,opacity] duration-300 ease-default",
      "before:rounded-full before:bg-current",
      "data-ending-style:scale-95 data-ending-style:opacity-0",
      "data-starting-style:scale-95 data-starting-style:opacity-0",
      "data-unchecked:hidden",
    ],
  },
  variants: {
    size: {
      lg: {
        radio: "size-5",
        radioIndicator: "before:size-3",
      },
      md: {
        radio: "size-4.5",
        radioIndicator: "before:size-2.5",
      },
      sm: {
        radio: "size-4",
        radioIndicator: "before:size-2",
      },
    },
  },
  defaultVariants: {
    size: "md",
  },
});

type RadioGroupVariantProps = VariantProps<typeof radioGroup>;

export { radioGroup };
export type { RadioGroupVariantProps };

"use client";

import { mergeProps, useDirection, useRender } from "@base-ui/react";
import { Radio as BaseRadio } from "@base-ui/react/radio";
import { RadioGroup as BaseRadioGroup } from "@base-ui/react/radio-group";
import { createContext, useContext } from "react";

import { mergeSlotClassName } from "@/registry/sector23/lib/merge-base-ui";

import { radioGroup, type RadioGroupVariantProps } from "./radio-group.style";

type RadioGroupContext = RadioGroupVariantProps;

const RadioGroupContext = createContext<RadioGroupContext>({
  size: "md",
});

function useRadioGroup() {
  return useContext(RadioGroupContext);
}

function RadioGroup({
  size,
  className,
  children,
  ...props
}: BaseRadioGroup.Props & RadioGroupVariantProps) {
  const direction = useDirection();

  return (
    <RadioGroupContext.Provider value={{ size }}>
      <BaseRadioGroup
        data-slot="radio-group"
        className={mergeSlotClassName(radioGroup().root, className)}
        {...props}
        dir={direction}
      >
        {children}
      </BaseRadioGroup>
    </RadioGroupContext.Provider>
  );
}

function RadioGroupLegend({
  className,
  render,
  ...props
}: useRender.ComponentProps<"div">) {
  const legend = useRender({
    defaultTagName: "div",
    props: {
      ...mergeProps({ className: radioGroup().legend({ className }) }, props),
      "data-slot": "radio-group-legend",
    },
    render,
  });

  return legend;
}

function Radio({ className, ...props }: BaseRadio.Root.Props) {
  const { size } = useRadioGroup();

  return (
    <BaseRadio.Root
      data-slot="radio"
      className={mergeSlotClassName(radioGroup({ size }).radio, className)}
      {...props}
    />
  );
}

function RadioIndicator({ className, ...props }: BaseRadio.Indicator.Props) {
  const { size } = useRadioGroup();

  return (
    <BaseRadio.Indicator
      data-slot="radio-indicator"
      className={mergeSlotClassName(
        radioGroup({ size }).radioIndicator,
        className,
      )}
      {...props}
    />
  );
}

export { RadioGroup, RadioGroupLegend, Radio, RadioIndicator };
